import { describe, it, expect, vi } from "vitest";
import {
  createImagePreviewGate,
  drawImagePreview,
} from "../src/chat/image-preview-gate.js";

// verify-32: a preview cancelled by a page switch / newer batch must never
// commit its late completion onto the current (newer) page, while the current
// page still displays its own preview normally.
describe("verify-32: preview cancellation must not write a stale result to a newer page", () => {
  it("rejects the stale batch when a newer batch is requested and resolves only the newer result", async () => {
    const workers = [];
    const gate = createImagePreviewGate({
      workerFactory: () => {
        const worker = { postMessage() {}, terminate: vi.fn() };
        workers.push(worker);
        return worker;
      },
    });
    const stale = gate.validate([{ data: "stale" }]);
    const staleRejected = expect(stale).rejects.toThrow("cancelled");
    // Page switch: a newer batch replaces the in-flight one.
    const current = gate.validate([{ data: "current" }]);
    // The stale worker completes late; its result must not win.
    workers[0].onmessage({ data: { results: ["stale-result"] } });
    workers[1].onmessage({ data: { results: ["current-result"] } });
    await staleRejected;
    expect(await current).toEqual(["current-result"]);
    // The stale worker's decoder was terminated at cancellation time; the
    // current worker terminates only after it completes normally.
    expect(workers[0].terminate).toHaveBeenCalledOnce();
    expect(workers[1].terminate).toHaveBeenCalledOnce();
  });

  it("closes bitmaps that arrive after cancellation instead of committing them to a new page", async () => {
    const worker = { postMessage() {}, terminate: vi.fn() };
    const gate = createImagePreviewGate({ workerFactory: () => worker });
    const pending = gate.validate([{ data: "image" }]);
    const rejected = expect(pending).rejects.toThrow("cancelled");
    gate.cancel();
    const staleBitmap = { close: vi.fn() };
    // A late transfer of decoded frames must be disposed, never retained.
    worker.onmessage({
      data: { results: [{ thumbnails: [{ bitmap: staleBitmap }] }] },
    });
    await rejected;
    expect(staleBitmap.close).toHaveBeenCalledOnce();
    expect(worker.terminate).toHaveBeenCalledOnce();
  });

  it("draws the current page's preview frame immediately", () => {
    const context = { clearRect() {}, drawImage: vi.fn() };
    const canvas = { getContext: () => context };
    const stop = drawImagePreview(canvas, {
      repetitions: Infinity,
      thumbnails: [{ bitmap: "frameA", duration: 0 }],
    });
    expect(context.drawImage).toHaveBeenCalledWith("frameA", 0, 0);
    expect(canvas.__ccPreviewDrawn).toBe(true);
    stop();
  });

  it("advances a multi-frame preview while active and halts every frame after cancellation", async () => {
    vi.useFakeTimers();
    try {
      const context = { clearRect() {}, drawImage: vi.fn() };
      const stop = drawImagePreview(
        { getContext: () => context },
        {
          repetitions: 1,
          thumbnails: [
            { bitmap: "frameA", duration: 30 },
            { bitmap: "frameB", duration: 30 },
          ],
        },
      );
      expect(context.drawImage).toHaveBeenLastCalledWith("frameA", 0, 0);
      await vi.advanceTimersByTimeAsync(30);
      expect(context.drawImage).toHaveBeenLastCalledWith("frameB", 0, 0);
      // Cancellation: no further frames may be drawn onto the canvas.
      stop();
      const committed = context.drawImage.mock.calls.length;
      await vi.advanceTimersByTimeAsync(1000);
      expect(context.drawImage.mock.calls.length).toBe(committed);
    } finally {
      vi.useRealTimers();
    }
  });

  it("stops the stale animation so a new preview on the same canvas is not overwritten", async () => {
    vi.useFakeTimers();
    try {
      const context = { clearRect() {}, drawImage: vi.fn() };
      const canvas = { getContext: () => context };
      // Page A preview starts animating.
      const stopStale = drawImagePreview(canvas, {
        repetitions: Infinity,
        thumbnails: [
          { bitmap: "pageA-0", duration: 20 },
          { bitmap: "pageA-1", duration: 20 },
        ],
      });
      expect(context.drawImage).toHaveBeenLastCalledWith("pageA-0", 0, 0);
      // Page switch reuses the same canvas; cancel page A before drawing page B.
      stopStale();
      context.drawImage.mockClear();
      drawImagePreview(canvas, {
        repetitions: Infinity,
        thumbnails: [{ bitmap: "pageB", duration: 0 }],
      });
      expect(context.drawImage).toHaveBeenLastCalledWith("pageB", 0, 0);
      // The stale timer, if not cleared, would have written pageA-1 here.
      await vi.advanceTimersByTimeAsync(1000);
      expect(context.drawImage.mock.calls.length).toBe(1);
      expect(context.drawImage).toHaveBeenLastCalledWith("pageB", 0, 0);
    } finally {
      vi.useRealTimers();
    }
  });
});

